content.content:
1	/* =============================================================================
2	   Boppa Llewyn × Starlight
3	
4	   The Boppa Llewyn design system on Starlight: Geist and Geist Mono, neutral
5	   greys with the logo green as the one accent, 6/10/16px corners, hairlines
6	   between things and shadows only on cards and the screenshot window. It is the
7	   theme Doctored's documentation site wears (its public-docs/src/styles/custom.css),
8	   carried over rule for rule so the two sites look like one family; only
9	   Prettier's formatting differs. Change it there and here together. Frame Job's
10	   own components are styled in frame-job.css, which loads after this file.
11	
12	   The --bl-* tokens are in tokens.css, copied whole from the design system:
13	   Neutral Light under [data-theme='light'] and Neutral Dark under
14	   [data-theme='dark']. This file maps them onto Starlight's --sl-* properties
15	   and styles the parts those properties cannot reach, so every colour here is
16	   a token and both looks come from the one mapping.
17	
18	   This file is unlayered, so it wins over every Starlight cascade layer. The
19	   @font-face rules are in src/fonts/font-face.css and the Expressive Code settings
20	   in astro.config.mjs.
21	   ============================================================================= */
22	
23	/* --- Type and layout ---------------------------------------------------- */
24	/* Plain `:root`, so FeatureIndex's `:root:has(.fj-features)` still outranks the
25	   content width. */
26	:root {
27	  --sl-font: var(--bl-font-sans);
28	  --sl-font-mono: var(--bl-font-mono);
29	
30	  --sl-text-body: 1rem; /* 16px, `body` */
31	  --sl-text-code: 0.875rem; /* 14px, `code` */
32	  --sl-line-height: 1.625; /* 26px */
33	  --sl-line-height-headings: 1.1;
34	
35	  /* h1 is 32px below 50rem and 40px from it; the others hold at every width. */
36	  --sl-text-h1: 2rem;
37	  --sl-text-h2: 1.75rem; /* 28px */
38	  --sl-text-h3: 1.25rem; /* 20px */
39	  --sl-text-h4: 1.0625rem; /* 17px */
40	
41	  --sl-nav-height: 4rem; /* 64px */
42	  --sl-nav-gap: 1.5rem;
43	  --sl-sidebar-width: 17.5rem; /* 280px */
44	  --sl-content-width: 42.5rem; /* --bl-prose-width, 680px */
45	  --sl-content-gap-y: 1rem;
46	  --sl-menu-button-size: 2.25rem; /* 36px */
47	}
48	
49	@media (min-width: 50em) {
50	  :root {
51	    --sl-nav-height: 4rem;
52	    --sl-nav-pad-x: 1.5rem;
53	    --sl-text-h1: 2.5rem;
54	    --sl-text-h2: 1.75rem;
55	    --sl-text-h3: 1.25rem;
56	    --sl-text-h4: 1.0625rem;
57	  }
58	}
59	
60	/* --- Colour: one mapping, both looks (tokens.css switches the values) ---- */
61	:root,
62	::backdrop {
63	  --sl-color-white: var(--bl-ink);
64	  --sl-color-gray-1: var(--bl-ink);
65	  --sl-color-gray-2: var(--bl-ink-muted);
66	  --sl-color-gray-3: var(--bl-ink-subtle);
67	  --sl-color-gray-4: var(--bl-line-strong);
68	  --sl-color-gray-5: var(--bl-line);
69	  --sl-color-gray-6: var(--bl-surface);
