215	/* =============================================================================
216	   Site layer — the parts of the design the variables above cannot reach,
217	   in order down the page.
218	
219	   Everything here is unlayered too, so it beats Starlight's own
220	   `starlight.core` / `starlight.components` / `starlight.content` layers
221	   regardless of specificity. Values come from the handoff's "The parts, in
222	   order down the page".
223	   ============================================================================= */
224	
225	/* --- Layout metrics ----------------------------------------------------- */
226	:root {
227	  --sl-content-pad-x: 1rem; /* 16px gutter on a phone */
228	}
229	
230	@media (min-width: 50rem) {
231	  :root {
232	    --sl-content-pad-x: 1.5rem;
233	  }
234	}
235	
236	/* Splash pages (no sidebar) run to the design's 1120px container rather than
237	   Starlight's 1080px. The extra `[data-has-hero]` lifts specificity over the
238	   `html:not([data-has-sidebar])` rule Starlight inlines in <head>. */
239	html[data-has-hero]:not([data-has-sidebar]) {
240	  --sl-content-width: 70rem;
241	}
242	
243	/* --- Header: 64px, solid surface, one hairline, no blur ----------------- */
244	header.header {
245	  background-color: var(--sl-color-bg-nav);
246	  border-bottom: 1px solid var(--sl-color-hairline-shade);
247	}
248	
249	/* The search field sits at the end of its column, beside the icon buttons. */
250	.header .sl-flex:has(> site-search) {
251	  justify-content: flex-end;
252	}
253	
254	/* The theme toggle, then GitHub, 24px apart, with no divider. */
255	.header .right-group {
256	  gap: 1.5rem;
257	}
258	
259	.header .right-group .social-icons {
260	  order: 1;
261	}
262	
263	.header .social-icons::after {
264	  content: none;
265	}
266	
267	/* --- Search ------------------------------------------------------------- */
268	/* A 260 × 36px field on the sunken surface. */
269	@media (min-width: 50rem) {
270	  site-search button[data-open-modal] {
271	    width: 16.25rem;
272	    max-width: 100%;
273	    height: 2.25rem;
274	    gap: 0.5rem;
275	    padding-inline: 0.75rem 0.5rem;
276	    background-color: var(--bl-surface-sunken);
277	    border: 1px solid var(--bl-line);
278	    border-radius: var(--bl-radius-md);
279	    color: var(--bl-ink-subtle);
280	    font-size: 0.875rem;
281	  }
282	
283	  site-search button[data-open-modal]:hover {
284	    border-color: var(--bl-line-strong);
285	    color: var(--bl-ink-subtle);
286	  }
287	
288	  site-search button[data-open-modal] svg {
289	    font-size: 1rem;
290	  }
291	}
292	
293	/* The ⌘K hint: two small keys and no box around the pair. Its display is set
294	   here because the theme's `kbd` rule would otherwise outrank `sl-hidden`. */
295	site-search button > kbd {
296	  display: none;
297	  gap: 2px;
298	  height: auto;
299	  min-width: 0;
300	  padding: 0;
301	  background-color: transparent;
302	  border: 0;
303	}
304	
305	@media (min-width: 50rem) {
306	  site-search button > kbd {
307	    display: flex;
308	  }
309	}
310	
311	site-search kbd kbd {
312	  height: 1.25rem;
313	  min-width: 1.25rem;
314	  font-size: 0.75rem;
315	}
316	
317	/* Below the sidebar breakpoint the search control is a 36px ghost button with
318	   a 44px hit area. */
319	@media (width < 50rem) {
320	  site-search button[data-open-modal] {
321	    position: relative;
322	    width: var(--sl-menu-button-size);
323	    height: var(--sl-menu-button-size);
324	    justify-content: center;
325	    padding: 0;
326	    border: 0;
327	    border-radius: var(--bl-radius-md);
328	    background-color: transparent;
329	    color: var(--bl-ink-muted);
