334	    color: var(--bl-ink);
335	  }
336	
337	  site-search button[data-open-modal]::after {
338	    content: '';
339	    position: absolute;
340	    inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
341	  }
