722	
723	/* Headers: eyebrows 10px above a strong rule. */
724	.sl-markdown-content th:not(:where(.not-content *)) {
725	  padding-top: 0;
726	  color: var(--bl-ink-subtle);
727	  border-bottom: 1px solid var(--bl-line-strong);
728	}
729	
730	.sl-markdown-content td:not(:where(.not-content *)) {
731	  border-bottom: 1px solid var(--bl-line);
732	}
733	
734	/* Commands and identifiers in tables never break mid-token. */
735	.sl-markdown-content :is(th, td) > code {
736	  white-space: nowrap;
737	}
738	
739	/* --- Asides: a full tint, the icon and the word, no border -------------- */
740	.starlight-aside {
741	  border: 0;
742	  border-radius: var(--bl-radius-md);
743	  padding: 1rem 1.25rem;
744	  font-size: 0.9375rem;
745	  line-height: 1.5rem; /* 15 / 24 */
746	}
747	
748	.sl-markdown-content .starlight-aside:not(:first-child) {
749	  margin-top: 1.5rem;
750	}
751	
752	.starlight-aside__title {
753	  gap: 0.75rem;
754	  font-size: 0.9375rem;
755	  font-weight: 600;
756	  line-height: 1.5rem;
757	  color: var(--sl-color-asides-text-accent);
758	}
759	
760	.starlight-aside__icon {
761	  width: 1.25rem;
762	  height: 1.25rem;
763	  font-size: inherit;
764	  flex-shrink: 0;
765	}
766	
767	/* The note's icon is the quieter ink; the other three share their title's. */
768	.starlight-aside--note .starlight-aside__icon {
769	  color: var(--sl-color-blue);
770	}
771	
772	.starlight-aside__title + .starlight-aside__content {
773	  margin-top: 0.125rem;
774	}
775	
776	/* The body hangs under the title, clear of the icon (20px + 12px). */
777	.starlight-aside__content {
778	  padding-inline-start: 2rem;
779	  color: var(--bl-ink-muted);
780	}
781	
782	/* --- Code --------------------------------------------------------------- */
783	/* Starlight sets these at theme level, past astro.config.mjs's reach: the code
784	   on the sunken surface, the title tab one with the bar, and no accent line. */
785	.expressive-code {
786	  --ec-frm-edBg: var(--bl-surface-sunken);
787	  --ec-frm-trmBg: var(--bl-surface-sunken);
788	  --ec-frm-edActTabBg: var(--bl-surface);
789	  --ec-frm-edActTabIndTopCol: transparent;
790	  --ec-frm-frameBoxShdCssVal: none;
791	}
792	
793	.expressive-code figcaption .title {
794	  font-family: var(--sl-font-mono);
795	  font-weight: 500;
796	  font-size: 0.75rem;
797	  line-height: 1rem;
798	  letter-spacing: 0;
799	  text-transform: none;
800	  color: var(--bl-ink-subtle);
801	}
802	
803	.sl-markdown-content .expressive-code:not(:first-child) {
804	  margin-top: 1.5rem;
805	}
806	
807	.sl-markdown-content code:not(:where(.not-content *, pre *)) {
808	  font-size: 0.875em;
809	  background-color: var(--bl-surface-sunken);
810	  border-radius: var(--bl-radius-sm);
811	  padding: 0.125rem 0.3125rem;
812	}
813	
814	.sl-markdown-content blockquote:not(:where(.not-content *)) {
815	  border-inline-start-color: var(--bl-line);
816	}
817	
818	/* --- Keys: anywhere a key is shown, search included --------------------- */
819	kbd {
820	  display: inline-flex;
821	  align-items: center;
822	  justify-content: center;
823	  min-width: 1.5rem;
824	  height: 1.5rem;
825	  padding: 0 0.375rem;
826	  font-family: var(--sl-font-mono);
827	  font-weight: 500;
828	  font-size: 0.8125rem;
829	  line-height: 1;
830	  color: var(--bl-ink);
831	  background-color: var(--bl-surface);
832	  border: 1px solid var(--bl-line);
833	  border-bottom-width: 2px;
834	  border-radius: var(--bl-radius-sm);
835	  vertical-align: 1px;
836	}
837	
838	/* --- Buttons ------------------------------------------------------------ */
839	.sl-link-button {
840	  font-size: 1rem;
841	  font-weight: 550;
842	  line-height: 1.5rem;
843	  padding: 0.75rem 1.25rem;
844	  border-radius: var(--bl-radius-md);
845	}
846	
847	.sl-link-button.primary {
848	  background: var(--bl-accent);
849	  color: var(--bl-on-accent);
850	  border: 1px solid transparent;
851	}
852	
853	.sl-link-button.primary:hover {
854	  background: var(--bl-accent-hover);
855	  color: var(--bl-on-accent);
856	  text-decoration: none;
857	}
858	
859	.sl-link-button.secondary {
860	  background: var(--bl-surface);
861	  color: var(--bl-ink);
862	  border: 1px solid var(--bl-line-strong);
863	}
864	
865	.sl-link-button.secondary:hover {
866	  background: var(--bl-surface-sunken);
867	  color: var(--bl-ink);
868	}
869	
870	.sl-link-button.minimal {
871	  color: var(--bl-ink);
872	  padding-inline: 0.75rem;
873	}
874	
875	.sl-link-button.minimal:hover {
876	  background: var(--bl-surface-sunken);
877	  color: var(--bl-ink);
878	}
879	
880	.sl-link-button svg {
881	  width: 1rem;
882	  height: 1rem;
883	}
884	
885	/* --- Cards and link cards ----------------------------------------------- */
886	.card-grid {
887	  gap: 1.5rem;
888	}
889	
890	.card,
891	.sl-link-card {
892	  background-color: var(--bl-surface);
893	  border: 1px solid var(--bl-line);
894	  border-radius: var(--bl-radius-lg);
895	  box-shadow: var(--bl-shadow-card);
896	  padding: 1.5rem;
897	}
898	
899	/* A hover only strengthens the border: nothing lifts or changes fill. */
900	.card:hover,
901	.sl-link-card:hover {
902	  background-color: var(--bl-surface);
903	  border-color: var(--bl-line-strong);
904	}
905	
906	.sl-link-card {
907	  align-items: center;
908	  gap: 1rem;
909	}
910	
911	.sl-link-card .stack {
912	  gap: 0.25rem;
913	}
914	
915	/* Titles are `heading-3`. */
916	.card .title,
917	.sl-link-card .title {
918	  font-size: 1.25rem;
919	  font-weight: 600;
920	  line-height: 1.75rem;
921	  letter-spacing: -0.01em;
922	  color: var(--bl-ink);
923	}
924	
925	.card {
926	  gap: 0.5rem;
927	}
928	
929	.card .title {
930	  gap: 0.75rem;
931	}
932	
933	.card .body,
934	.sl-link-card .description {
935	  font-size: 0.9375rem;
936	  line-height: 1.375rem; /* 15 / 22 */
937	  color: var(--bl-ink-muted);
938	}
939	
940	/* The icon chip loses its box. */
941	.card .icon {
942	  border: 0;
943	  background-color: transparent;
944	  padding: 0;
945	  border-radius: 0;
946	  color: var(--bl-ink-subtle);
947	}
948	
949	.sl-link-card .icon,
950	.sl-link-card:hover .icon {
951	  color: var(--bl-ink-subtle);
952	}
953	
954	/* --- Pagination: two cards, 16px apart, 64px below the body ------------- */
955	.sl-container > footer {
956	  margin-top: 4rem;
957	  gap: 2rem;
958	}
959	
960	.pagination-links {
961	  gap: 1rem;
962	}
963	
964	.pagination-links a {
965	  padding: 1rem 1.25rem;
966	  background-color: var(--bl-surface);
967	  border: 1px solid var(--bl-line);
968	  border-radius: var(--bl-radius-lg);
969	  box-shadow: var(--bl-shadow-card);
970	  font-size: 0.875rem;
971	  line-height: 1.25rem;
972	  color: var(--bl-ink-subtle);
973	}
974	
975	.pagination-links a:hover {
976	  border-color: var(--bl-line-strong);
977	}
978	
979	.pagination-links br {
980	  display: none;
981	}
982	
983	.pagination-links .link-title {
984	  display: block;
985	  margin-top: 2px;
986	  font-size: 1.25rem;
987	  font-weight: 600;
988	  line-height: 1.75rem;
989	  letter-spacing: -0.01em;
990	  color: var(--bl-ink);
991	}
992	
993	/* --- Footer meta: under a hairline, 32px below the pagination ----------- */
994	/* Starlight puts it above the pagination; `order` moves it below. */
995	footer .meta {
996	  order: 1;
997	  margin-top: 0;
998	  padding-top: 1rem;
999	  border-top: 1px solid var(--bl-line);
1000	  font-size: 0.875rem;
1001	  line-height: 1.25rem;
1002	  color: var(--bl-ink-subtle);
1003	}
1004	
1005	footer .meta:empty {
1006	  display: none;
1007	}
1008	
1009	footer .meta a {
1010	  color: var(--bl-ink-subtle);
1011	}
1012	
1013	footer .meta a:hover {
1014	  color: var(--bl-ink);
1015	}
1016	
1017	/* --- Splash ------------------------------------------------------------- */
1018	/* The hero band runs the full viewport width on `--bl-band`: a spread shadow
1019	   paints past the container on both sides and the clip keeps it to the
1020	   hero's own height. Neither makes the page scroll sideways. */
1021	.hero {
1022	  background-color: var(--bl-band);
1023	  color: var(--bl-on-band);
1024	  box-shadow: 0 0 0 100vmax var(--bl-band);
1025	  clip-path: inset(0 -100vmax);
1026	  grid-template-columns: minmax(0, 1fr);
1027	  gap: 2rem;
1028	  padding-block: 4rem;
1029	}
1030	
1031	/* The Frame Job mark: 96px above the text on a phone, 192px beside it from
1032	   50rem. */
1033	.hero > img,
1034	.hero > .hero-html {
1035	  order: -1;
1036	  width: 6rem;
1037	  height: 6rem;
1038	  margin-inline: 0;
1039	}
1040	
1041	.hero .stack {
1042	  gap: 2rem;
1043	  text-align: start;
1044	}
1045	
1046	.hero .copy {
1047	  gap: 0;
1048	  align-items: flex-start;
1049	}
1050	
1051	.hero .actions {
1052	  gap: 0.75rem;
1053	  justify-content: flex-start;
1054	}
1055	
1056	@media (min-width: 50rem) {
1057	  .hero {
1058	    grid-template-columns: minmax(0, 1fr) 192px;
1059	    gap: 3rem;
1060	    padding-block: 6rem;
1061	  }
1062	
1063	  .hero > img,
1064	  .hero > .hero-html {
1065	    order: 2;
1066	    width: 192px;
1067	    height: 192px;
1068	  }
1069	}
1070	
1071	.hero .page-eyebrow {
1072	  color: var(--bl-on-band);
1073	  opacity: 0.8;
1074	}
1075	
1076	/* `display`: 40/42 on a phone, 64/64 from 50rem */
1077	.hero h1 {
1078	  font-size: 2.5rem;
1079	  line-height: 2.625rem;
1080	  letter-spacing: -0.035em;
1081	  color: var(--bl-on-band);
1082	}
1083	
1084	.hero .page-eyebrow + h1 {
1085	  margin-top: 0.75rem;
1086	}
1087	
1088	@media (min-width: 50rem) {
1089	  .hero h1 {
1090	    font-size: 4rem;
1091	    line-height: 4rem;
1092	  }
1093	}
1094	
1095	/* `lede`, 24px below the title */
1096	.hero .tagline {
1097	  max-width: 34em;
1098	  margin-top: 1.5rem;
1099	  font-size: 1.0625rem;
1100	  line-height: 1.625rem;
1101	  color: var(--bl-on-band);
1102	  opacity: 0.86;
1103	}
1104	
1105	@media (min-width: 50rem) {
1106	  .hero .tagline {
1107	    font-size: 1.1875rem;
1108	    line-height: 1.875rem;
1109	  }
1110	}
1111	
1112	/* The hero sits right under the header; the panel keeps the space below the
1113	   last block. */
1114	html[data-has-hero] .content-panel {
1115	  padding-block: 0 6rem;
1116	}
1117	
1118	/* The body starts 40px below the band on a phone, 64px from 50rem. */
1119	html[data-has-hero] .content-panel .sl-markdown-content {
1120	  margin-top: 2.5rem;
1121	}
1122	
1123	@media (min-width: 50rem) {
1124	  html[data-has-hero] .content-panel {
1125	    padding-block: 0 9rem;
1126	  }
1127	
1128	  html[data-has-hero] .content-panel .sl-markdown-content {
1129	    margin-top: 4rem;
1130	  }
1131	}
1132	
1133	/* The requirements paragraph under the window: muted, prose-wide, 48px down. */
1134	[data-has-hero] .sl-markdown-content > .fj-shot + p {
1135	  max-width: var(--bl-prose-width);
1136	  margin-top: 3rem;
1137	  color: var(--bl-ink-muted);
1138	}
1139	
1140	/* Each section heading: a hairline with 64px above it and 64px below it. */
1141	[data-has-hero] .sl-markdown-content > :is(h2, .sl-heading-wrapper.level-h2) {
1142	  margin-top: 4rem;
1143	  padding-top: 4rem;
1144	  border-top: 1px solid var(--bl-line);
1145	}
1146	
1147	[data-has-hero] .sl-markdown-content > :is(h2, .sl-heading-wrapper.level-h2) + * {
1148	  margin-top: 1.5rem;
1149	}
1150

