/* =============================================================================
   Boppa Llewyn × Starlight

   The Boppa Llewyn design system on Starlight: Geist and Geist Mono, neutral
   greys with the logo green as the one accent, 6/10/16px corners, hairlines
   between things and shadows only on cards and the screenshot window. It is the
   theme Doctored's documentation site wears (its public-docs/src/styles/custom.css),
   carried over rule for rule so the two sites look like one family; only
   Prettier's formatting differs. Change it there and here together. Frame Job's
   own components are styled in frame-job.css, which loads after this file.

   The --bl-* tokens are in tokens.css, copied whole from the design system:
   Neutral Light under [data-theme='light'] and Neutral Dark under
   [data-theme='dark']. This file maps them onto Starlight's --sl-* properties
   and styles the parts those properties cannot reach, so every colour here is
   a token and both looks come from the one mapping.

   This file is unlayered, so it wins over every Starlight cascade layer. The
   @font-face rules are in src/fonts/font-face.css and the Expressive Code settings
   in astro.config.mjs.
   ============================================================================= */

/* --- Type and layout ---------------------------------------------------- */
/* Plain `:root`, so FeatureIndex's `:root:has(.fj-features)` still outranks the
   content width. */
:root {
  --sl-font: var(--bl-font-sans);
  --sl-font-mono: var(--bl-font-mono);

  --sl-text-body: 1rem; /* 16px, `body` */
  --sl-text-code: 0.875rem; /* 14px, `code` */
  --sl-line-height: 1.625; /* 26px */
  --sl-line-height-headings: 1.1;

  /* h1 is 32px below 50rem and 40px from it; the others hold at every width. */
  --sl-text-h1: 2rem;
  --sl-text-h2: 1.75rem; /* 28px */
  --sl-text-h3: 1.25rem; /* 20px */
  --sl-text-h4: 1.0625rem; /* 17px */

  --sl-nav-height: 4rem; /* 64px */
  --sl-nav-gap: 1.5rem;
  --sl-sidebar-width: 17.5rem; /* 280px */
  --sl-content-width: 42.5rem; /* --bl-prose-width, 680px */
  --sl-content-gap-y: 1rem;
  --sl-menu-button-size: 2.25rem; /* 36px */
}

@media (min-width: 50em) {
  :root {
    --sl-nav-height: 4rem;
    --sl-nav-pad-x: 1.5rem;
    --sl-text-h1: 2.5rem;
    --sl-text-h2: 1.75rem;
    --sl-text-h3: 1.25rem;
    --sl-text-h4: 1.0625rem;
  }
}

/* --- Colour: one mapping, both looks (tokens.css switches the values) ---- */
:root,
::backdrop {
  --sl-color-white: var(--bl-ink);
  --sl-color-gray-1: var(--bl-ink);
  --sl-color-gray-2: var(--bl-ink-muted);
  --sl-color-gray-3: var(--bl-ink-subtle);
  --sl-color-gray-4: var(--bl-line-strong);
  --sl-color-gray-5: var(--bl-line);
  --sl-color-gray-6: var(--bl-surface);
  --sl-color-gray-7: var(--bl-surface-sunken);
  --sl-color-black: var(--bl-bg);

  --sl-color-text: var(--bl-ink);
  --sl-color-text-accent: var(--bl-accent-ink);
  --sl-color-text-invert: var(--bl-on-accent);
  --sl-color-accent-low: var(--bl-accent-soft);
  --sl-color-accent: var(--bl-accent);
  --sl-color-accent-high: var(--bl-accent-ink);

  --sl-color-bg: var(--bl-bg);
  --sl-color-bg-nav: var(--bl-surface);
  --sl-color-bg-sidebar: var(--bl-bg);
  --sl-color-bg-inline-code: var(--bl-surface-sunken);
  --sl-color-bg-accent: var(--bl-accent);
  --sl-color-hairline: var(--bl-line);
  --sl-color-hairline-light: var(--bl-line);
  --sl-color-hairline-shade: var(--bl-line);
  --sl-color-backdrop-overlay: rgba(24, 24, 27, 0.4);

  /* The asides' hues: note is neutral, tip the accent, caution and danger
     their own. Green is Starlight's success badge. */
  --sl-color-blue-low: var(--bl-surface-sunken);
  --sl-color-blue: var(--bl-ink-muted);
  --sl-color-blue-high: var(--bl-ink);
  --sl-color-purple-low: var(--bl-accent-soft);
  --sl-color-purple: var(--bl-accent);
  --sl-color-purple-high: var(--bl-accent-ink);
  --sl-color-green-low: var(--bl-accent-soft);
  --sl-color-green: var(--bl-accent);
  --sl-color-green-high: var(--bl-accent-ink);
  --sl-color-orange-low: var(--bl-caution-soft);
  --sl-color-orange: var(--bl-caution);
  --sl-color-orange-high: var(--bl-caution);
  --sl-color-red-low: var(--bl-danger-soft);
  --sl-color-red: var(--bl-danger);
  --sl-color-red-high: var(--bl-danger);

  /* The card shadow; the window shadow is for the search dialog only. */
  --sl-shadow-sm: var(--bl-shadow-card);
  --sl-shadow-md: var(--bl-shadow-window);
  --sl-shadow-lg: var(--bl-shadow-window);
}

:root[data-theme='dark'],
[data-theme='dark'] ::backdrop {
  --sl-color-backdrop-overlay: rgba(0, 0, 0, 0.6);
}

/* --- Headings: Geist 600, each level its own line height --------------- */
h1,
h2,
h3,
h4,
h5,
h6 {
  font-weight: 600;
  font-style: normal;
  color: var(--sl-color-white);
}

h1 {
  letter-spacing: -0.03em;
  line-height: 2.75rem; /* 40 / 44 */
}

@media (width < 50rem) {
  h1 {
    line-height: 2.25rem; /* 32 / 36 */
  }
}

.sl-markdown-content :is(h2, .sl-heading-wrapper.level-h2) {
  letter-spacing: -0.02em;
  line-height: 2.125rem; /* 28 / 34 */
}

.sl-markdown-content :is(h3, .sl-heading-wrapper.level-h3) {
  letter-spacing: -0.01em;
  line-height: 1.75rem; /* 20 / 28 */
}

.sl-markdown-content :is(h4, .sl-heading-wrapper.level-h4) {
  letter-spacing: 0;
  line-height: 1.5rem; /* 17 / 24 */
}

/* Eyebrows: the page eyebrow, sidebar group labels, the ToC label, table
   headers and the mobile ToC's current section. Mono 500 12/16, uppercase. */
.page-eyebrow,
.sidebar-content .group-label .large,
.right-sidebar-panel h2,
mobile-starlight-toc .display-current,
.sl-markdown-content th {
  font-family: var(--sl-font-mono);
  font-weight: 500;
  font-size: 0.75rem;
  line-height: 1rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* --- Links -------------------------------------------------------------- */
.sl-markdown-content a:not(:where(.sl-link-card *, .sl-link-button, .not-content *)) {
  color: var(--sl-color-text-accent);
  text-decoration: none;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.sl-markdown-content a:not(:where(.sl-link-card *, .sl-link-button, .not-content *)):hover {
  color: var(--sl-color-text-accent);
  text-decoration: underline;
}

/* --- Focus: one outline everywhere -------------------------------------- */
:focus-visible {
  outline: 2px solid var(--bl-focus);
  outline-offset: 2px;
}

/* Full-width rows in a fixed bar keep the ring inside their box. */
mobile-starlight-toc :is(summary, a):focus-visible {
  outline-offset: var(--sl-outline-offset-inside);
}

/* --- Motion: colour, background and border only, at 120ms -------------- */
a,
button,
summary,
input,
.sl-link-card,
.card {
  transition:
    color 120ms,
    background-color 120ms,
    border-color 120ms;
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0.01ms !important;
  }
}

/* =============================================================================
   Site layer — the parts of the design the variables above cannot reach,
   in order down the page.

   Everything here is unlayered too, so it beats Starlight's own
   `starlight.core` / `starlight.components` / `starlight.content` layers
   regardless of specificity. Values come from the handoff's "The parts, in
   order down the page".
   ============================================================================= */

/* --- Layout metrics ----------------------------------------------------- */
:root {
  --sl-content-pad-x: 1rem; /* 16px gutter on a phone */
}

@media (min-width: 50rem) {
  :root {
    --sl-content-pad-x: 1.5rem;
  }
}

/* Splash pages (no sidebar) run to the design's 1120px container rather than
   Starlight's 1080px. The extra `[data-has-hero]` lifts specificity over the
   `html:not([data-has-sidebar])` rule Starlight inlines in <head>. */
html[data-has-hero]:not([data-has-sidebar]) {
  --sl-content-width: 70rem;
}

/* --- Header: 64px, solid surface, one hairline, no blur ----------------- */
header.header {
  background-color: var(--sl-color-bg-nav);
  border-bottom: 1px solid var(--sl-color-hairline-shade);
}

/* The search field sits at the end of its column, beside the icon buttons. */
.header .sl-flex:has(> site-search) {
  justify-content: flex-end;
}

/* The theme toggle, then GitHub, 24px apart, with no divider. */
.header .right-group {
  gap: 1.5rem;
}

.header .right-group .social-icons {
  order: 1;
}

.header .social-icons::after {
  content: none;
}

/* --- Search ------------------------------------------------------------- */
/* A 260 × 36px field on the sunken surface. */
@media (min-width: 50rem) {
  site-search button[data-open-modal] {
    width: 16.25rem;
    max-width: 100%;
    height: 2.25rem;
    gap: 0.5rem;
    padding-inline: 0.75rem 0.5rem;
    background-color: var(--bl-surface-sunken);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-md);
    color: var(--bl-ink-subtle);
    font-size: 0.875rem;
  }

  site-search button[data-open-modal]:hover {
    border-color: var(--bl-line-strong);
    color: var(--bl-ink-subtle);
  }

  site-search button[data-open-modal] svg {
    font-size: 1rem;
  }
}

/* The ⌘K hint: two small keys and no box around the pair. Its display is set
   here because the theme's `kbd` rule would otherwise outrank `sl-hidden`. */
site-search button > kbd {
  display: none;
  gap: 2px;
  height: auto;
  min-width: 0;
  padding: 0;
  background-color: transparent;
  border: 0;
}

@media (min-width: 50rem) {
  site-search button > kbd {
    display: flex;
  }
}

site-search kbd kbd {
  height: 1.25rem;
  min-width: 1.25rem;
  font-size: 0.75rem;
}

/* Below the sidebar breakpoint the search control is a 36px ghost button with
   a 44px hit area. */
@media (width < 50rem) {
  site-search button[data-open-modal] {
    position: relative;
    width: var(--sl-menu-button-size);
    height: var(--sl-menu-button-size);
    justify-content: center;
    padding: 0;
    border: 0;
    border-radius: var(--bl-radius-md);
    background-color: transparent;
    color: var(--bl-ink-muted);
  }

  site-search button[data-open-modal]:hover {
    background-color: var(--bl-surface-sunken);
    color: var(--bl-ink);
  }

  site-search button[data-open-modal]::after {
    content: '';
    position: absolute;
    inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
  }

  site-search button[data-open-modal] svg {
    font-size: 1rem;
  }
}

site-search dialog {
  border-color: var(--bl-line);
}

@media (min-width: 50rem) {
  site-search dialog {
    border-radius: var(--bl-radius-lg);
  }
}

#starlight__search {
  --pagefind-ui-border-radius: var(--bl-radius-md);
  --pagefind-ui-background: var(--bl-surface);
  --pagefind-ui-border: var(--bl-line-strong);
  --pagefind-ui-tag: var(--bl-surface-sunken);
}

#starlight__search input:focus {
  --pagefind-ui-border: var(--bl-focus);
}

/* --- Icon buttons: the theme toggle and GitHub -------------------------- */
/* ThemeSelect draws the toggle's 36px ghost button; its icons are sized here,
   because Starlight's Icon sets their size in a later layer than a component's. */
.theme-toggle svg {
  width: 1.125rem;
  height: 1.125rem;
}

.header .social-icons a {
  width: 2.25rem;
  height: 2.25rem;
  margin: 0;
  padding: 0;
  align-items: center;
  justify-content: center;
  border-radius: var(--bl-radius-md);
  color: var(--bl-ink-muted);
}

.header .social-icons a:hover {
  background-color: var(--bl-surface-sunken);
  color: var(--bl-ink);
}

.header .social-icons a svg {
  width: 1.125rem;
  height: 1.125rem;
}

/* --- Menu button -------------------------------------------------------- */
/* Starlight's filled circle with a shadow becomes the 36px ghost button the
   other header controls are. 36px is under the 44px minimum touch target, so
   the hit area is expanded past the visual box with a pseudo-element. */
.sl-menu-button {
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: var(--bl-radius-md);
  background-color: transparent;
  color: var(--bl-ink-muted);
  box-shadow: none;
}

.sl-menu-button:hover,
.sl-menu-button:has(~ :popover-open) {
  background-color: var(--bl-surface-sunken);
  color: var(--bl-ink);
  box-shadow: none;
}

.sl-menu-button svg {
  width: 1.125rem;
  height: 1.125rem;
}

/* 36px box, 44px target: the pseudo-element is the thing the finger hits. */
.sl-menu-button::after {
  content: '';
  position: absolute;
  inset: calc((var(--sl-menu-button-size) - 2.75rem) / 2);
}

/* --- Sidebar ------------------------------------------------------------ */
.sidebar-content {
  padding: 2rem 1rem 3rem 1.5rem;
}

/* 28px between top-level groups */
.sidebar-content .top-level > li + li {
  margin-top: 1.75rem;
}

/* Group labels: eyebrows 8px above their links (the gap is the open list's,
   so a closed group adds none). */
.sidebar-content summary {
  padding: 0 0.625rem;
  line-height: 1rem;
}

/* A group inside a group keeps a link's height, so closed ones don't crowd. */
.sidebar-content ul ul summary {
  padding-block: 0.375rem;
}

.sidebar-content .group-label .large {
  color: var(--bl-ink-subtle);
}

.sidebar-content summary .caret {
  color: var(--bl-ink-subtle);
}

/* A flat list: no tree line, the links 1px apart. */
.sidebar-content ul ul {
  display: grid;
  gap: 1px;
  margin-top: 0.5rem;
}

.sidebar-content ul ul li {
  margin-inline-start: 0;
  border-inline-start: 0;
  padding-inline-start: 0;
}

.sidebar-content a,
.sidebar-content a.large {
  font-size: 0.9375rem; /* 15px */
  font-weight: 400;
  line-height: 1.25rem;
  padding: 0.375rem 0.625rem;
  border-radius: var(--bl-radius-sm);
  color: var(--bl-ink-muted);
}

/* Guarded against `[aria-current]` so the current-page pill survives a hover:
   an unlayered `a:hover` would otherwise outrank it. */
.sidebar-content a:not([aria-current='page']):is(:hover, :focus-visible) {
  background-color: var(--bl-surface-sunken);
  color: var(--bl-ink);
}

.sidebar-content a[aria-current='page'],
.sidebar-content a[aria-current='page']:is(:hover, :focus) {
  background-color: var(--bl-accent-soft);
  color: var(--bl-accent-ink);
  font-weight: 550;
}

/* --- Table of contents -------------------------------------------------- */
/* No column rule: the list's own hairline is the ToC's one line. */
.right-sidebar {
  border-inline-start: 0;
}

.right-sidebar-panel {
  padding-top: 3.5rem;
}

.right-sidebar-panel h2 {
  color: var(--bl-ink-subtle);
  margin-bottom: 0.75rem;
}

.right-sidebar-panel nav > ul {
  border-inline-start: 1px solid var(--bl-line);
}

.right-sidebar-panel nav a {
  border-radius: 0;
  border-inline-start: 2px solid transparent;
  margin-inline-start: -1px; /* sit the rail on top of the list hairline */
  padding-block: 0.3125rem;
  padding-inline: calc(1rem * var(--depth) + 0.75rem) 0;
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: var(--bl-ink-muted);
}

.right-sidebar-panel nav a:hover {
  color: var(--bl-ink);
}

.right-sidebar-panel nav a[aria-current='true'] {
  border-inline-start-color: var(--bl-accent);
  color: var(--bl-ink);
  font-weight: 500;
}

/* Mobile ToC bar: a flat strip under the header, not a bordered pill in a bar. */
mobile-starlight-toc nav {
  background-color: var(--bl-surface);
  border-top: 0;
}

mobile-starlight-toc summary {
  border-bottom: 1px solid var(--bl-line);
  font-size: 0.875rem;
  padding-inline: var(--sl-content-pad-x);
}

mobile-starlight-toc .toggle {
  border: 0;
  border-radius: 0;
  background-color: transparent;
  color: var(--bl-ink-muted);
  padding-inline: 0;
  gap: 0.5rem;
}

mobile-starlight-toc .toggle .caret {
  order: -1; /* the chevron leads the label */
}

mobile-starlight-toc details[open] .toggle,
mobile-starlight-toc details .toggle:hover {
  border-color: transparent;
  color: var(--bl-ink);
}

mobile-starlight-toc .display-current {
  margin-inline-start: auto; /* parked at the end of the bar */
  color: var(--bl-ink-subtle);
}

mobile-starlight-toc .dropdown {
  background-color: var(--bl-surface);
  border-color: var(--bl-line);
  border-radius: 0 0 var(--bl-radius-lg) var(--bl-radius-lg);
  box-shadow: var(--bl-shadow-card);
}

mobile-starlight-toc .isMobile a {
  border-top-color: var(--bl-line);
  color: var(--bl-ink-muted);
}

mobile-starlight-toc .isMobile a[aria-current='true'] {
  color: var(--bl-ink);
}

/* --- The page opener ---------------------------------------------------- */
/* 56px under the header to the eyebrow (40px on a phone), 16px from the
   description to the first block, 144px below the last block (96px on a
   phone). No hairline between the opener and the body. */
.content-panel:first-of-type {
  padding-block: 2.5rem 0;
}

.content-panel + .content-panel {
  border-top: 0;
  padding-top: 1rem;
}

.content-panel:last-of-type {
  padding-bottom: 6rem;
}

@media (min-width: 50rem) {
  .content-panel:first-of-type {
    padding-top: 3.5rem;
  }

  .content-panel:last-of-type {
    padding-bottom: 9rem;
  }
}

.page-eyebrow {
  color: var(--bl-accent-ink);
}

/* `lede`: 17/26 on a phone, 19/30 from 50rem */
.page-description {
  font-size: 1.0625rem;
  line-height: 1.625rem;
  color: var(--bl-ink-muted);
}

@media (min-width: 50rem) {
  .page-description {
    font-size: 1.1875rem;
    line-height: 1.875rem;
  }
}

/* --- Body --------------------------------------------------------------- */
/* Blocks 16px apart (--sl-content-gap-y), list items 6px. */
.sl-markdown-content li + li:not(:where(.not-content *)) {
  margin-top: 0.375rem;
}

.sl-markdown-content strong {
  font-weight: 600;
}

/* h2: 48px above, 12px below; h3: 32px above, 8px below. */
.sl-markdown-content :is(h2, .sl-heading-wrapper.level-h2):not(:where(.not-content *)) {
  margin-top: 3rem;
}

.sl-markdown-content :is(h2, .sl-heading-wrapper.level-h2) + :not(.sl-anchor-link) {
  margin-top: 0.75rem;
}

.sl-markdown-content :is(h3, .sl-heading-wrapper.level-h3):not(:where(.not-content *)) {
  margin-top: 2rem;
}

.sl-markdown-content :is(h3, .sl-heading-wrapper.level-h3) + :not(.sl-anchor-link) {
  margin-top: 0.5rem;
}

.sl-markdown-content > :first-child {
  margin-top: 0;
}

/* --- Steps: numbered squares on a hairline ------------------------------ */
.sl-steps {
  --bullet-size: 1.75rem; /* 28px */
  --bullet-margin: 0.25rem;
}

.sl-steps > li {
  padding-inline-start: 3rem;
}

.sl-steps > li::before {
  line-height: calc(var(--bullet-size) - 2px);
  font-family: var(--sl-font-mono);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--bl-ink);
  background-color: var(--bl-surface-sunken);
  border: 1px solid var(--bl-line);
  border-radius: var(--bl-radius-sm);
  box-shadow: none;
}

.sl-steps > li::after {
  background-color: var(--bl-line);
}

.sl-steps > li:last-child::after {
  display: none;
}

.sl-steps > li:last-child > :last-child {
  margin-bottom: 0;
}

/* --- Tables ------------------------------------------------------------- */
/* Starlight makes tables `display: block` so wide ones scroll on their own.
   The design asks for a full-width table instead, which needs a real table box. */
.sl-markdown-content table:not(:where(.not-content *)) {
  display: table;
  width: 100%;
  border-collapse: collapse;
  font-size: 0.9375rem;
  line-height: 1.375rem; /* 15 / 22 */
}

.sl-markdown-content table:not(:first-child) {
  margin-top: 1.5rem;
}

.sl-markdown-content :is(th, td):not(:where(.not-content *)) {
  border: 0;
  padding: 0.625rem 0.75rem 0.625rem 0;
  text-align: start;
  vertical-align: top;
}

/* Headers: eyebrows 10px above a strong rule. */
.sl-markdown-content th:not(:where(.not-content *)) {
  padding-top: 0;
  color: var(--bl-ink-subtle);
  border-bottom: 1px solid var(--bl-line-strong);
}

.sl-markdown-content td:not(:where(.not-content *)) {
  border-bottom: 1px solid var(--bl-line);
}

/* Commands and identifiers in tables never break mid-token. */
.sl-markdown-content :is(th, td) > code {
  white-space: nowrap;
}

/* --- Asides: a full tint, the icon and the word, no border -------------- */
.starlight-aside {
  border: 0;
  border-radius: var(--bl-radius-md);
  padding: 1rem 1.25rem;
  font-size: 0.9375rem;
  line-height: 1.5rem; /* 15 / 24 */
}

.sl-markdown-content .starlight-aside:not(:first-child) {
  margin-top: 1.5rem;
}

.starlight-aside__title {
  gap: 0.75rem;
  font-size: 0.9375rem;
  font-weight: 600;
  line-height: 1.5rem;
  color: var(--sl-color-asides-text-accent);
}

.starlight-aside__icon {
  width: 1.25rem;
  height: 1.25rem;
  font-size: inherit;
  flex-shrink: 0;
}

/* The note's icon is the quieter ink; the other three share their title's. */
.starlight-aside--note .starlight-aside__icon {
  color: var(--sl-color-blue);
}

.starlight-aside__title + .starlight-aside__content {
  margin-top: 0.125rem;
}

/* The body hangs under the title, clear of the icon (20px + 12px). */
.starlight-aside__content {
  padding-inline-start: 2rem;
  color: var(--bl-ink-muted);
}

/* --- Code --------------------------------------------------------------- */
/* Starlight sets these at theme level, past astro.config.mjs's reach: the code
   on the sunken surface, the title tab one with the bar, and no accent line. */
.expressive-code {
  --ec-frm-edBg: var(--bl-surface-sunken);
  --ec-frm-trmBg: var(--bl-surface-sunken);
  --ec-frm-edActTabBg: var(--bl-surface);
  --ec-frm-edActTabIndTopCol: transparent;
  --ec-frm-frameBoxShdCssVal: none;
}

.expressive-code figcaption .title {
  font-family: var(--sl-font-mono);
  font-weight: 500;
  font-size: 0.75rem;
  line-height: 1rem;
  letter-spacing: 0;
  text-transform: none;
  color: var(--bl-ink-subtle);
}

.sl-markdown-content .expressive-code:not(:first-child) {
  margin-top: 1.5rem;
}

.sl-markdown-content code:not(:where(.not-content *, pre *)) {
  font-size: 0.875em;
  background-color: var(--bl-surface-sunken);
  border-radius: var(--bl-radius-sm);
  padding: 0.125rem 0.3125rem;
}

.sl-markdown-content blockquote:not(:where(.not-content *)) {
  border-inline-start-color: var(--bl-line);
}

/* --- Keys: anywhere a key is shown, search included --------------------- */
kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.5rem;
  height: 1.5rem;
  padding: 0 0.375rem;
  font-family: var(--sl-font-mono);
  font-weight: 500;
  font-size: 0.8125rem;
  line-height: 1;
  color: var(--bl-ink);
  background-color: var(--bl-surface);
  border: 1px solid var(--bl-line);
  border-bottom-width: 2px;
  border-radius: var(--bl-radius-sm);
  vertical-align: 1px;
}

/* --- Buttons ------------------------------------------------------------ */
.sl-link-button {
  font-size: 1rem;
  font-weight: 550;
  line-height: 1.5rem;
  padding: 0.75rem 1.25rem;
  border-radius: var(--bl-radius-md);
}

.sl-link-button.primary {
  background: var(--bl-accent);
  color: var(--bl-on-accent);
  border: 1px solid transparent;
}

.sl-link-button.primary:hover {
  background: var(--bl-accent-hover);
  color: var(--bl-on-accent);
  text-decoration: none;
}

.sl-link-button.secondary {
  background: var(--bl-surface);
  color: var(--bl-ink);
  border: 1px solid var(--bl-line-strong);
}

.sl-link-button.secondary:hover {
  background: var(--bl-surface-sunken);
  color: var(--bl-ink);
}

.sl-link-button.minimal {
  color: var(--bl-ink);
  padding-inline: 0.75rem;
}

.sl-link-button.minimal:hover {
  background: var(--bl-surface-sunken);
  color: var(--bl-ink);
}

.sl-link-button svg {
  width: 1rem;
  height: 1rem;
}

/* --- Cards and link cards ----------------------------------------------- */
.card-grid {
  gap: 1.5rem;
}

.card,
.sl-link-card {
  background-color: var(--bl-surface);
  border: 1px solid var(--bl-line);
  border-radius: var(--bl-radius-lg);
  box-shadow: var(--bl-shadow-card);
  padding: 1.5rem;
}

/* A hover only strengthens the border: nothing lifts or changes fill. */
.card:hover,
.sl-link-card:hover {
  background-color: var(--bl-surface);
  border-color: var(--bl-line-strong);
}

.sl-link-card {
  align-items: center;
  gap: 1rem;
}

.sl-link-card .stack {
  gap: 0.25rem;
}

/* Titles are `heading-3`. */
.card .title,
.sl-link-card .title {
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.75rem;
  letter-spacing: -0.01em;
  color: var(--bl-ink);
}

.card {
  gap: 0.5rem;
}

.card .title {
  gap: 0.75rem;
}

.card .body,
.sl-link-card .description {
  font-size: 0.9375rem;
  line-height: 1.375rem; /* 15 / 22 */
  color: var(--bl-ink-muted);
}

/* The icon chip loses its box. */
.card .icon {
  border: 0;
  background-color: transparent;
  padding: 0;
  border-radius: 0;
  color: var(--bl-ink-subtle);
}

.sl-link-card .icon,
.sl-link-card:hover .icon {
  color: var(--bl-ink-subtle);
}

/* --- Pagination: two cards, 16px apart, 64px below the body ------------- */
.sl-container > footer {
  margin-top: 4rem;
  gap: 2rem;
}

.pagination-links {
  gap: 1rem;
}

.pagination-links a {
  padding: 1rem 1.25rem;
  background-color: var(--bl-surface);
  border: 1px solid var(--bl-line);
  border-radius: var(--bl-radius-lg);
  box-shadow: var(--bl-shadow-card);
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: var(--bl-ink-subtle);
}

.pagination-links a:hover {
  border-color: var(--bl-line-strong);
}

.pagination-links br {
  display: none;
}

.pagination-links .link-title {
  display: block;
  margin-top: 2px;
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.75rem;
  letter-spacing: -0.01em;
  color: var(--bl-ink);
}

/* --- Footer meta: under a hairline, 32px below the pagination ----------- */
/* Starlight puts it above the pagination; `order` moves it below. */
footer .meta {
  order: 1;
  margin-top: 0;
  padding-top: 1rem;
  border-top: 1px solid var(--bl-line);
  font-size: 0.875rem;
  line-height: 1.25rem;
  color: var(--bl-ink-subtle);
}

footer .meta:empty {
  display: none;
}

footer .meta a {
  color: var(--bl-ink-subtle);
}

footer .meta a:hover {
  color: var(--bl-ink);
}

/* --- Splash ------------------------------------------------------------- */
/* The hero band runs the full viewport width on `--bl-band`: a spread shadow
   paints past the container on both sides and the clip keeps it to the
   hero's own height. Neither makes the page scroll sideways. */
.hero {
  background-color: var(--bl-band);
  color: var(--bl-on-band);
  box-shadow: 0 0 0 100vmax var(--bl-band);
  clip-path: inset(0 -100vmax);
  grid-template-columns: minmax(0, 1fr);
  gap: 2rem;
  padding-block: 4rem;
}

/* The Frame Job mark: 96px above the text on a phone, 192px beside it from
   50rem. */
.hero > img,
.hero > .hero-html {
  order: -1;
  width: 6rem;
  height: 6rem;
  margin-inline: 0;
}

.hero .stack {
  gap: 2rem;
  text-align: start;
}

.hero .copy {
  gap: 0;
  align-items: flex-start;
}

.hero .actions {
  gap: 0.75rem;
  justify-content: flex-start;
}

@media (min-width: 50rem) {
  .hero {
    grid-template-columns: minmax(0, 1fr) 192px;
    gap: 3rem;
    padding-block: 6rem;
  }

  .hero > img,
  .hero > .hero-html {
    order: 2;
    width: 192px;
    height: 192px;
  }
}

.hero .page-eyebrow {
  color: var(--bl-on-band);
  opacity: 0.8;
}

/* `display`: 40/42 on a phone, 64/64 from 50rem */
.hero h1 {
  font-size: 2.5rem;
  line-height: 2.625rem;
  letter-spacing: -0.035em;
  color: var(--bl-on-band);
}

.hero .page-eyebrow + h1 {
  margin-top: 0.75rem;
}

@media (min-width: 50rem) {
  .hero h1 {
    font-size: 4rem;
    line-height: 4rem;
  }
}

/* `lede`, 24px below the title */
.hero .tagline {
  max-width: 34em;
  margin-top: 1.5rem;
  font-size: 1.0625rem;
  line-height: 1.625rem;
  color: var(--bl-on-band);
  opacity: 0.86;
}

@media (min-width: 50rem) {
  .hero .tagline {
    font-size: 1.1875rem;
    line-height: 1.875rem;
  }
}

/* The hero sits right under the header; the panel keeps the space below the
   last block. */
html[data-has-hero] .content-panel {
  padding-block: 0 6rem;
}

/* The body starts 40px below the band on a phone, 64px from 50rem. */
html[data-has-hero] .content-panel .sl-markdown-content {
  margin-top: 2.5rem;
}

@media (min-width: 50rem) {
