---
/* Boppa Llewyn header lockup, as on Doctored's site: the company mark (three toy blocks), the
   company's name, a slash, the product's name and a mono version badge — "Boppa Llewyn / Frame
   Job v0.3". Below 50rem the company's name and the slash hide. Starlight's own SiteTitle renders
   the logo image and the title text only, and cannot carry the rest. */
import { Image } from 'astro:assets';
import { logos } from 'virtual:starlight/user-images';
import { APP_VERSION } from '../site';

/* The mark is an SVG drawn on a 1024px square: the header shows it at 32px, and one file serves
   every pixel density, so it takes no `densities`. Its alt is empty because the company's name
   follows it as text. */
const iconAttrs = { width: 32, height: 32, alt: '' };

const { siteTitle, siteTitleHref } = Astro.locals.starlightRoute;
---

<a href={siteTitleHref} class="site-title sl-flex">
  {logos.dark && (
    <Image
      src={logos.dark}
      {...iconAttrs}
      class:list={{ 'light:sl-hidden': Boolean(logos.light && logos.light !== logos.dark) }}
    />
  )}
  {logos.light && logos.light !== logos.dark && (
    <Image src={logos.light} {...iconAttrs} class="dark:sl-hidden" />
  )}
  <span class="company">Boppa Llewyn</span>
  <span class="sep" aria-hidden="true">
    /
  </span>
  <span class="wordmark" translate="no">
    {siteTitle}
  </span>
  <span class="version" translate="no">
    v{APP_VERSION}
  </span>
</a>

<style>
  @layer starlight.core {
    .site-title {
      align-items: center;
      gap: 0.5rem;
/* Boppa Llewyn design tokens, generated from the design system's tokens.json.
   Every name is the system's own, prefixed --bl-. The site ships Neutral Light
   (data-theme="light") and Neutral Dark (data-theme="dark"); the other three palettes
   are at the end, under data-bl-palette, for comparison only. */

:root,
:root[data-theme='light'],
[data-theme='light'] ::backdrop {
  --bl-brand-cream: #fbf8f1;
  --bl-brand-green: #1f8564;
  --bl-brand-yellow: #f2c14e;
  --bl-brand-coral: #f4653f;
  --bl-brand-forest: #1d651f;
  --bl-brand-outline: #101915;
  --bl-bg: #fafafa;
  --bl-surface: #ffffff;
  --bl-surface-sunken: #f1f1f3;
  --bl-band: #f1f1f3;
  --bl-on-band: #18181b;
  --bl-line: #e4e4e7;
  --bl-line-strong: #85858d;
  --bl-ink: #18181b;
  --bl-ink-muted: #56565e;
  --bl-ink-subtle: #6b6b73;
  --bl-accent: #1a7a5b;
  --bl-accent-hover: #146a4e;
  --bl-on-accent: #ffffff;
  --bl-accent-soft: #e3f2ec;
  --bl-accent-ink: #14644a;
  --bl-focus: #1a7a5b;
  --bl-caution: #8a5a00;
  --bl-caution-soft: #fdf3d9;
  --bl-danger: #b3261e;
  --bl-danger-soft: #fde8e6;
  --bl-shadow-card: 0 1px 2px rgba(24, 24, 27, 0.06);
  --bl-shadow-window: 0 24px 48px -12px rgba(24, 24, 27, 0.18), 0 0 0 1px rgba(24, 24, 27, 0.08);
}

:root[data-theme='dark'],
[data-theme='dark'] ::backdrop {
  --bl-brand-cream: #fbf8f1;
  --bl-brand-green: #1f8564;
  --bl-brand-yellow: #f2c14e;
  --bl-brand-coral: #f4653f;
  --bl-brand-forest: #1d651f;
  --bl-brand-outline: #101915;
  --bl-bg: #131315;
  --bl-surface: #1b1b1e;
  --bl-surface-sunken: #0e0e10;
  --bl-band: #1b1b1e;
  --bl-on-band: #f2f2f3;
  --bl-line: #2c2c31;
  --bl-line-strong: #6e6e78;
  --bl-ink: #f2f2f3;
  --bl-ink-muted: #a6a6ae;
  --bl-ink-subtle: #8c8c95;
  --bl-accent: #4cc39a;
  --bl-accent-hover: #6fd4ae;
  --bl-on-accent: #0a1f17;
  --bl-accent-soft: #173328;

