72:.steps { list-style: none; padding: 0; counter-reset: s; }
73:.steps li { position: relative; padding: 0 0 20px 48px; margin: 0; counter-increment: s; }
74:.steps li::before { content: counter(s); position: absolute; left: 0; top: -1px; width: 28px; height: 28px; display: grid; place-items: center; font: 500 13px/1 var(--bl-font-mono); color: var(--bl-ink); background: var(--bl-surface-sunken); border: 1px solid var(--bl-line); border-radius: var(--bl-radius-sm); }
75:.steps li::after { content: ""; position: absolute; left: 14px; top: 32px; bottom: 4px; width: 1px; background: var(--bl-line); }
76:.steps li:last-child::after { display: none; }
77:.steps li:last-child { padding-bottom: 0; }
